<script setup lang="ts">
import { t as uiText } from '@/locales'

import {partnerError} from '@/utils/partnerError'
import {computed,onBeforeUnmount,reactive,ref,watch} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import ResearchSampleSourceFields from './components/ResearchSampleSourceFields.vue'
import SampleSourceSummary from './components/SampleSourceSummary.vue'
import {sampleDomains,sampleKinds,sampleDomainHelp,sampleDomain,sampleReceiptLabel,sampleRoute,researchSampleProgress} from '@/utils/sampleDomains'
import type {SampleDomain} from '@/types/samples'
import PageContainer from '@/components/PageContainer/index.vue'
import BusinessFields from './BusinessFields.vue'
import PartnerFacts from './PartnerFacts.vue'
