import PartnerFiles from './PartnerFiles.vue'
import PartnerPhoto from './PartnerPhoto.vue'
import SelectionReceiptDialog from './selection/SelectionReceiptDialog.vue'
import PartnerProductCatalog from './PartnerProductCatalog.vue'
import PartnerProductSpecs from './PartnerProductSpecs.vue'
import PartnerImportDialog from './PartnerImportDialog.vue'
import PartnerOperationsPanel from './operations/PartnerOperationsPanel.vue'
import PartnerListingPanel from './operations/PartnerListingPanel.vue'
import OperationSpecPicker from './operations/OperationSpecPicker.vue'
import PhoneObjectIdSelect from '@/components/PhoneObjectSelect/IdSelect.vue'
import type { PhoneObjectOption } from '@/components/PhoneObjectSelect/types'
import SharedCompatiblePhoneSelector from '@/views/mold/components/SharedCompatiblePhoneSelector.vue'
import {partnerPage,partnerDetail,partnerSave,partnerAction,partnerOptions,sampleSources,sampleMovements,newRequestId,uploadPartnerFile,deletePartnerProduct,deletePartnerSpec} from '@/api/modules/partner'
import {selectionDetail,selectionRow} from '@/api/modules/partnerSelections'
import type {SelectionRow} from '@/types/partnerSelections'
import {useUserStore} from '@/stores/user'
