import type {SampleIdentity} from '@/types/sampleManagement'
import {useCollaborationWorkspace} from '@/stores/collaborationWorkspace'
import type {PartnerKind,PartnerRow,PartnerPage,PartnerOptions,BusinessData,BusinessField,FieldOption} from '@/types/partner'
const route=useRoute(),router=useRouter(),user=useUserStore(),workspace=useCollaborationWorkspace()
const kind=computed(()=>String(route.meta.partnerKind||'partner-products') as PartnerKind)
const titles:Record<PartnerKind,string>={'partner-products':'产品目录','partner-sales':'销售跟进',samples:'样品管理'}
const names:Record<string,string>={draft:'草稿',pending:'待确认',adopted:'已采用',inactive:'停用',active:'在用',quoted:'报价已确认',confirmed:'订单已确认',closed:'已关闭',reopen:'重新办理',receive:'实际收样',opening:'期初登记',retain:'确认留样',loan:'借出',return:'归还',move:'移动位置',gift:'赠送',consume:'耗用',scrap:'在库报废',loss:'借出损失',count:'盘点／更正',undo:'原记录更正',file_add:'添加资料',product_save:'保存产品资料',product_delete:'删除产品',spec_delete:'删除规格',sale_save:'保存询价／订单',quote_confirm:'确认报价',order_confirm:'确认订单',agreement:'确认结算约定',receipt:'客户收款',refund:'客户退款',ship:'正常发货',reship:'补发',returngoods:'退货',cancel:'取消数量',shipreverse:'发货更正',supplierpay:'支付供方／抵佣',supplierrefund:'收到供方退款',feereceipt:'收到佣金',feerefund:'退回佣金',offsetreverse:'佣金抵扣冲回',amend:'订单调整',close:'关闭订单',source_resolve:'补充来源'}
const label=(v:unknown)=>names[String(v)]||String(v||'待补')
const id=computed(()=>Number(route.query.id||0)),detail=ref<PartnerRow>(),page=ref<PartnerPage>({content:[],totalElements:0,page:1,size:30,totalPages:0})
const options=ref<PartnerOptions>({specs:[],suppliers:[],customers:[],canReadMoney:false,canWriteMoney:false,canConfirmMoney:false})
const loading=ref(false),busy=ref(false),error=ref(''),tab=ref('work'),listTab=ref('ledger'),refs=ref<BusinessData[]>([])
const sampleScope=computed(()=>String(route.meta.sampleDomain||''))
const sampleSourceOptions=computed(()=>{const scope=sampleScope.value||filters.domain;return [{value:'model',label:'产品型号样品'},{value:'device',label:'历史手机真机／模型机'},{value:'trial',label:'历史模具试模产出'},{value:'self',label:'研发／历史项目样品'},{value:'partner',label:'合作产品样品'},{value:'catalog',label:'目录选样样品'}].filter(o=>scope==='partner'?['partner','catalog'].includes(o.value):scope==='research'?o.value==='self':scope==='model'?['model','device','trial','self'].includes(o.value):true)})
const pageSize=computed(()=>kind.value==='samples'?50:30)
const filters=reactive({keyword:'',status:'',sourceType:'',domain:'',sampleKind:'',page:1}),importOpen=ref(false)
const dialog=ref(false),mode=ref(''),action=ref(''),form=ref<BusinessData>({}),dirty=ref(false),formError=ref(''),fields=ref<BusinessField[]>([]),extra=ref<BusinessField[]>([])
const sourceChoices=ref<BusinessData>({projects:[],rounds:[],nodes:[]}),pendingPhoto=ref<File>(),inspect=ref<BusinessData>(),inspectTitle=ref('')
const selectedQuoteSpec=ref<BusinessData>()
const mergeIdentityChoices=ref<SampleIdentity[]>([]),identityNeedsReview=ref(false)
async function findSampleIdentities(){const auth=user.token,requestId=form.value.requestId;try{const value=await sampleIdentityCandidates({...form.value});if(auth===user.token&&dialog.value&&form.value.requestId===requestId){mergeIdentityChoices.value=value.content;identityNeedsReview.value=value.requiresReview;if(!form.value.resolveSource&&!value.requiresReview&&value.content.length===1)form.value.sampleIdentityId=value.content[0]!.sampleIdentityId}}catch(e){if(auth===user.token)formError.value=partnerError(e)}}
const catalogSelection=ref<SelectionRow>(),catalogReceiptOpen=ref(false),catalogReceiptVersion=ref(0)
const deleting=ref(''),deletionError=ref('')
const canWrite=computed(()=>user.hasPermission(kind.value==='samples'?'samples:write':'partner:write'))
const canMoney=computed(()=>options.value.canWriteMoney&&options.value.canConfirmMoney)
const today=()=>new Date().toLocaleDateString('sv-SE')
const formatMoney=(v:unknown,curr?:string)=>v===undefined?'参考金额未记录':(curr||detail.value?.currency||'币种待补')+' '+(Number(v)/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})
const clone=<T,>(v:T):T=>JSON.parse(JSON.stringify(v))
const choices=(v:string[])=>v.map(x=>({value:x,label:label(x)}))
watch(()=>form.value.currency,(next,prev)=>{if(mode.value==='sale'&&prev&&next!==prev&&form.value.lines)form.value.lines.forEach((line:BusinessData)=>{delete line.unitPrice})})
const internalSkuObjects=computed<PhoneObjectOption[]>(()=>(options.value.internalSkus||[]).map(s=>({type:'sku',id:s.id,name:s.name,code:s.code,phoneModels:s.phoneModels||[]})))
const sampleProjectObjects=computed<PhoneObjectOption[]>(()=>(sourceChoices.value.projects||[]).map((p:BusinessData)=>({type:'product',id:p.id,name:p.name,code:p.code,phoneModels:p.phoneModels||[]})))
const supplierOptions=computed<FieldOption[]>(()=>options.value.suppliers.filter(s=>s.status!=='inactive').map(s=>({value:s.code,label:s.name+' · '+s.code})))
const customerOptions=computed<FieldOption[]>(()=>options.value.customers.filter(c=>c.status!=='inactive').map(c=>({value:c.customerId,label:c.customerName+' · '+c.customerCode})))
const lineOptions=computed<FieldOption[]>(()=>(detail.value?.lines||[]).map((l:BusinessData)=>({value:l.id,label:l.snapshot.specName+' · '+l.snapshot.supplierName})))
watch([()=>route.path,()=>route.query.id],()=>{detail.value=undefined;refs.value=[];selectedQuoteSpec.value=undefined;catalogSelection.value=undefined;deletionError.value=''},{flush:'sync'})
watch([kind,sampleScope],()=>{Object.assign(filters,{keyword:'',status:'',sourceType:'',domain:'',sampleKind:'',page:1});listTab.value='ledger';dialog.value=false;dirty.value=false})
let epoch=0,autoSource=''
async function load(reset=false){const serial=++epoch;loading.value=true;error.value='';if(reset)filters.page=1;if(route.query.new!=='1')autoSource=''
 try{const opt=await partnerOptions();if(serial!==epoch)return;options.value=opt
 if(id.value){const d=await partnerDetail(kind.value,id.value);if(serial!==epoch)return;detail.value=d;refs.value=clone(d.refs||[]);if(kind.value==='samples'&&['loan','return','move','retain'].includes(String(route.query.action||''))&&canWrite.value){startAction(String(route.query.action));const query={...route.query};delete query.action;void router.replace({path:route.path,query})}}
 else{detail.value=undefined;const params={...filters,...(kind.value==='samples'?{domain:sampleScope.value||filters.domain,size:pageSize.value}:{}),...Object.fromEntries(['productId','modelProductId','customerId','supplierCode','projectId'].filter(k=>route.query[k]).map(k=>[k,route.query[k]]))};const result=kind.value==='samples'&&listTab.value==='flows'?await sampleMovements(params):await partnerPage(kind.value,params);if(serial!==epoch)return;page.value=result}
 if(kind.value==='samples'&&!id.value&&!route.query.specId&&route.query.sourceType!=='catalog'&&route.query.new==='1'&&(route.query.projectId||['model','research'].includes(sampleScope.value))&&autoSource!==route.fullPath&&canWrite.value){autoSource=route.fullPath;await edit('',{sourceType:sampleScope.value==='model'?'model':'self',...(route.query.projectId?{projectId:Number(route.query.projectId),roundId:Number(route.query.roundId||0),nodeAuditId:Number(route.query.nodeAuditId||0)}:{})})}
 if(kind.value==='samples'&&route.query.selectionId&&route.query.selectionRowId&&route.query.sourceType==='catalog'&&route.query.new==='1'&&autoSource!==route.fullPath){autoSource=route.fullPath;if(!canWrite.value){error.value='当前账号没有实际收样权限。';return}const [sheet,selected]=await Promise.all([selectionDetail(Number(route.query.selectionId)),selectionRow(Number(route.query.selectionId),String(route.query.selectionRowId))]);if(serial!==epoch)return;catalogSelection.value=selected;catalogReceiptVersion.value=sheet.version;catalogReceiptOpen.value=true}
 if(kind.value==='partner-sales'&&route.query.customerId&&!route.query.specId&&route.query.new==='1'&&autoSource!==route.fullPath){autoSource=route.fullPath;await edit('inquiry')}
 }catch(e){error.value=partnerError(e)}finally{if(serial===epoch)loading.value=false}}
function closeCatalogReceipt(){catalogReceiptOpen.value=false;const {new:_new,sourceType:_source,selectionId:_sheet,selectionRowId:_row,...query}=route.query;void router.replace({path:route.path,query})}
function path(k:PartnerKind,n?:number){return {path:k==='samples'&&kind.value==='samples'?route.path:'/'+k,query:n?{id:String(n),...(kind.value==='samples'&&(route.query.customerContext||route.query.customerId)?{customerContext:String(route.query.customerContext||route.query.customerId)}:{}),from:route.query.new==='1'?String(route.query.from||'/'+k):route.fullPath}:{}}}
function switchListTab(value:string){page.value={...page.value,content:[]};listTab.value=value;void load(true)}
function open(row:BusinessData){if(listTab.value==='flows'&&kind.value==='samples')router.push(path('samples',row.sampleId));else router.push(path(kind.value,row.id))}
function link(k:PartnerKind,n:number){router.push(path(k,n))}
function researchSource(){const d=detail.value!;router.push({path:d.sourceSnapshot?.project?.development_mode==='launch_v1'?'/product-research':'/projects',query:{productId:d.projectId,from:route.fullPath}})}
function master(type:'customer'|'supplier',value:string|number){router.push({path:type==='customer'?'/customers/'+value:'/suppliers',query:{...(type==='supplier'?{code:value}:{}),from:route.fullPath}})}
function viewAll(){router.push({path:kind.value==='samples'?route.path:'/'+kind.value,query:{...(route.query.from?{from:String(route.query.from)}:{}),...(kind.value==='samples'&&(route.query.customerContext||route.query.customerId)?{customerContext:String(route.query.customerContext||route.query.customerId)}:{})}})}
function back(){const target=String(route.query.from||'');router.push(target.startsWith('/')?target:'/'+kind.value)}
watch(()=>route.fullPath,()=>{tab.value='work';void load()}, {immediate:true})
onBeforeUnmount(()=>{epoch++})
async function leave(){if(!dirty.value)return true;try{await ElMessageBox.confirm(uiText('本次填写尚未保存，确定离开？'),uiText('未保存内容'),{type:'warning'});return true}catch{return false}}
onBeforeRouteLeave(leave);onBeforeRouteUpdate(leave)
async function closeDialog(){if(dirty.value){try{await ElMessageBox.confirm(uiText('放弃本次未保存填写？'),uiText('关闭办理窗口'))}catch{return}}dialog.value=false;dirty.value=false}
function setDefaults(){form.value={requestId:newRequestId(),version:detail.value?.version||0,date:today(),qty:1,damaged:0,condition:'good',sourceType:sampleScope.value==='model'?'model':sampleScope.value==='research'?'self':'partner',sampleDomain:sampleScope.value||'partner',sampleKind:sampleScope.value==='model'?undefined:sampleScope.value==='research'?'prototype':'supplier',currency:'CNY',mode:'net',refs:clone(refs.value)};fields.value=[];extra.value=[];formError.value='';dirty.value=false;pendingPhoto.value=undefined}
async function projects(){const p=await sampleSources();sourceChoices.value.projects=p.projects||[];if(form.value.projectId)await projectChanged()}
async function projectChanged(){const r=await sampleSources(Number(form.value.projectId));sourceChoices.value.rounds=r.rounds||[];sourceChoices.value.nodes=r.nodes||[]}
function rememberSpecs(rows:BusinessData[]){options.value.specs=[...new Map([...options.value.specs,...rows].map(s=>[s.id,s])).values()]}
function specChanged(line:BusinessData,spec?:BusinessData){if(spec)rememberSpecs([spec]);const s=spec||options.value.specs.find(s=>s.id===line.specId);line.supplierCode=s?.details.sources?.[0]?.supplierCode||'';const src=s?.details.sources?.[0];if(src&&src.currency===(form.value.currency||'CNY'))line.unitPrice=src.unitPrice??(src.priceCents===undefined?undefined:String(src.priceCents/100));else delete line.unitPrice}
function supplierChanged(line:BusinessData){const src=sourceOptions(line).find((s:BusinessData)=>s.supplierCode===line.supplierCode);if(src?.currency===form.value.currency)line.unitPrice=src.unitPrice;else delete line.unitPrice}
function sourceOptions(line:BusinessData){return options.value.specs.find(s=>s.id===line.specId)?.details.sources||[]}
function addSpec(){form.value.specs.push({name:'',specification:'',phoneModelIds:[],websiteSku:'',sources:[{supplierCode:'',currency:''}]});dirty.value=true}
async function deleteProductEntry(row:PartnerRow,spec?:BusinessData){
 if(!canWrite.value||kind.value!=='partner-products'||deleting.value||busy.value)return
 const origin=route.fullPath,actorToken=user.token,requestId=newRequestId(),target=spec||row,keepRefs=JSON.stringify(refs.value)!==JSON.stringify(detail.value?.refs||[])
 deleting.value=(spec?'spec:':'product:')+target.id;deletionError.value=''
 try{
  try{await ElMessageBox.confirm(spec?uiText('删除规格“{value0}”（{value1}）？已有业务引用的规格会保留。',{value0:(spec.name),value1:(spec.code)}):uiText('删除产品“{value0}”（{value1}）及其 {value2} 个规格？已有业务引用或仍在上架的产品会保留。',{value0:(row.name),value1:(row.code),value2:(row.specs?.length||0)}),uiText('确认删除')+(spec?uiText('规格'):uiText('产品')),{type:'warning',confirmButtonText:uiText('确认删除'),cancelButtonText:uiText('取消'),closeOnClickModal:false})}catch{return}
  if(route.fullPath!==origin||user.token!==actorToken||!canWrite.value)return
  if(spec){const updated=await deletePartnerSpec(row.id,spec.id,{version:row.version,requestId});if(route.fullPath===origin&&user.token===actorToken){detail.value=updated;if(!keepRefs)refs.value=clone(updated.refs||[])}ElMessage.success(uiText('规格已删除'))}
  else{await deletePartnerProduct(row.id,{version:row.version,requestId});ElMessage.success(uiText('产品已删除'));if(route.fullPath!==origin||user.token!==actorToken||!canWrite.value)return
   if(id.value)await router.replace({path:'/partner-products'})
   else{filters.page=Math.min(filters.page,Math.max(1,Math.ceil((page.value.totalElements-1)/30)));await load()}
  }
 }catch(e){if(route.fullPath===origin&&user.token===actorToken)deletionError.value=partnerError(e)}finally{deleting.value=''}
}
function addLine(){form.value.lines.push({specId:undefined,supplierCode:'',qty:1});dirty.value=true}
async function edit(saleType='',seed:BusinessData={}){mergeIdentityChoices.value=[];identityNeedsReview.value=false;setDefaults();mode.value=kind.value==='partner-products'?'product':kind.value==='partner-sales'?'sale':'sample'
 if(mode.value==='product'){form.value={...(detail.value?clone(detail.value):{name:'',status:'draft',listing:'unrecorded',site:'',externalId:'',specs:[]}),refs:clone(refs.value),requestId:newRequestId()};if(!form.value.specs.length)addSpec();form.value.specs.forEach((s:BusinessData)=>{s.phoneModelIds ||= [];s.specification ??= s.name || '';if(!s.sources?.length)s.sources=[{supplierCode:'',currency:''}]})}
 else if(mode.value==='sale'){form.value={...(detail.value?clone(detail.value):{saleType:saleType||'inquiry',currency:'CNY',customerId:Number(route.query.customerId)||undefined,lines:[],notes:''}),refs:clone(refs.value),requestId:newRequestId()};if(!form.value.lines.length)addLine()}
 else{form.value={...form.value,...seed,qty:undefined,location:seed.location||'',ownerName:seed.ownerName||user.profile?.userName||''};if(seed.sourceType==='self'&&!sampleScope.value){form.value.sampleDomain='legacy';form.value.sampleKind=seed.sampleKind||'prototype'}if(!['model','research'].includes(form.value.sampleDomain)&&form.value.sourceType!=='catalog')await projects();if(form.value.sampleDomain==='legacy'&&!seed.nodeAuditId){const project=(sourceChoices.value.projects||[]).find((p:BusinessData)=>p.id===form.value.projectId);if(project?.projectKind==='product_research'||project?.developmentMode==='launch_v1')form.value.sampleDomain='research'}}
 dialog.value=true;dirty.value=false}
function changeSampleDomain(domain:string){form.value={...form.value,sampleDomain:domain,sourceType:domain==='model'?'model':domain==='research'?'self':'partner',sampleKind:domain==='model'?undefined:domain==='research'?'prototype':'supplier',modelProductId:undefined,projectId:undefined,roundId:undefined,nodeAuditId:undefined,moldSetId:undefined,phoneModelId:undefined,phoneModelIds:[],specId:undefined,supplierCode:'',trialBatch:'',provenance:''};dirty.value=true}
async function newFromProduct(type:'sample'|'quote',spec:BusinessData){if(type==='sample')router.push({path:'/partner-samples',query:{new:'1',specId:spec.id,supplierCode:spec.sources[0]?.supplierCode,from:route.fullPath}});else {selectedQuoteSpec.value=spec;tab.value='operations'}}
watch(()=>[kind.value,options.value.specs.length,route.query.new,route.query.specId],async()=>{if(route.query.new==='1'&&route.query.specId&&autoSource!==route.fullPath){autoSource=route.fullPath;if(kind.value==='samples')await edit('',{sourceType:'partner',specId:Number(route.query.specId),supplierCode:String(route.query.supplierCode||''),...(route.query.selectionId?{selectionId:Number(route.query.selectionId),selectionRowId:String(route.query.selectionRowId||'')}:{})});else if(kind.value==='partner-sales'){await edit('inquiry');form.value.lines[0].specId=Number(route.query.specId);specChanged(form.value.lines[0])}}})
function inspectRecord(title:string,value:BusinessData){inspectTitle.value=title;inspect.value=value}
function f(key:string,title:string,type:BusinessField['type']='text',opts?:FieldOption[],required=false):BusinessField{return {key,label:title,type,options:opts,required}}
function originalOptions(actionName:string){return (detail.value?.events||[]).filter((e:BusinessData)=>e.action===actionName).map((e:BusinessData)=>({value:e.id,label:label(e.action)+' · '+(e.data.date||String(e.time).slice(0,10))+' · '+(e.data.qty?e.data.qty+' 件':options.value.canReadMoney?formatMoney(e.data.amountCents):'原记录')}))}
async function loanProjects(){const request=form.value.requestId,token=user.token;try{const result=await sampleSources();if(dialog.value&&action.value==='loan'&&form.value.requestId===request&&user.token===token)sourceChoices.value.projects=result.projects||[]}catch(e){if(form.value.requestId===request)formError.value=partnerError(e)}}
function startAction(name:string,supplierCode='',loanId?:number){setDefaults();mode.value='action';action.value=name;const d=detail.value!;form.value.supplierCode=supplierCode;form.value.lineId=d.lines?.[0]?.id
 if(kind.value==='samples'&&name==='custody'){form.value.custody=clone(d.custody||[]);fields.value.push(f('reason','本次实际去向与保管分配说明','textarea',undefined,true))}
 else if(kind.value==='samples'){const b=d.balances,positions=(b.positions||[]).filter((p:BusinessData)=>p.name).map((p:BusinessData)=>({value:p.name,label:p.name+' · 可借 '+p.available+' · 留样 '+p.retained+' · 损坏 '+p.damaged}));form.value.location=positions[0]?.value
 if(!['loss','undo'].includes(name))fields.value.push(f('location',name==='return'?'放回位置':'取出／盘点位置','select',positions,true))
 if(['return','loss'].includes(name)){const loans=b.loans.filter((l:BusinessData)=>l.outstanding>0).map((l:BusinessData)=>({value:l.id,label:l.person+' · 待还 '+l.outstanding}));fields.value.unshift(f('loanId','原借用','select',loans,true));form.value.loanId=loanId||loans[0]?.value}
 if(name==='undo'){const reversed=new Set(d.events.filter((e:BusinessData)=>e.action==='undo').map((e:BusinessData)=>e.data.targetEventId));fields.value.push(f('targetEventId','原流转记录','select',d.events.filter((e:BusinessData)=>!['file_add','undo','source_resolve','custody'].includes(e.action)&&!reversed.has(e.id)).map((e:BusinessData)=>({value:e.id,label:label(e.action)+' · '+(e.data.qty||'')+' 件 · '+e.id})),true))}
 else fields.value.push(f(name==='count'?'actual':'qty',name==='count'?'实盘好品数量':'本次数量','number',undefined,true))
 if(['loan','gift'].includes(name)){const cid=Number(route.query.customerContext||route.query.customerId||0);if(cid){form.value.customerId=cid;form.value.person=options.value.customers.find(c=>c.customerId===cid)?.customerName||''}}
 if(name==='loan'){fields.value.push(f('person','接收人','text',undefined,true),f('due','预计归还日期','date',undefined,true));extra.value.push(f('customerId','关联客户（选填）','select',customerOptions.value))}
 if(name==='gift')extra.value.push(f('customerId','关联客户（选填）','select',customerOptions.value))
 if(name==='return')fields.value.push(f('damaged','其中损坏数量','number'))
 if(['move','scrap'].includes(name))fields.value.push(f('condition','样品状态','select',[{value:'good',label:'普通好品'},{value:'retained',label:'确认留样'},{value:'damaged',label:'损坏待处理'}]))
 if(name==='move')fields.value.push(f('to','目标位置','text',undefined,true))
 if(['gift','consume','scrap','loss','count','undo'].includes(name))fields.value.push(f('reason','接收人、用途或更正原因','textarea',undefined,true))
 }else{
 if(['quote_confirm','order_confirm','close'].includes(name)){}
 else if(name==='reopen'){fields.value.push(f('reason','重新办理原因','textarea',undefined,true))}
