 else{fields.value.push(f('lineId','订单明细','select',lineOptions.value,true),f('qty',name==='amend'?'调整后订购总数':'本次数量','number',undefined,true));if(['reship','returngoods','shipreverse'].includes(name))fields.value.push(f('originalEventId','原发货记录','select',originalOptions('ship'),true));if(name==='returngoods'){form.value.disposition='refund';fields.value.push(f('disposition','退货处理','select',[{value:'refund',label:'退货退款'},{value:'replace',label:'换货补发'}],true))}if(name==='amend')extra.value.push(f('unitPrice','调整后单价（不变可留空）','money'));if(name!=='ship')fields.value.push(f('reason','本次原因','textarea',undefined,true));extra.value.push(f('tracking','物流／运单'))}
 }
 if(!extra.value.some(x=>x.key==='date'))extra.value.push(f('date','实际日期（默认今天）','date'))
 if(!fields.value.some(x=>x.key==='reason'))extra.value.push(f('reason','说明','textarea'))
 dialog.value=true;dirty.value=false;if(kind.value==='samples'&&name==='loan'&&user.hasPermission('project:view'))void loanProjects()}
watch(()=>form.value.customerId,()=>{if(mode.value==='action'&&action.value==='loan'&&form.value.customerId)form.value.person=options.value.customers.find(c=>c.customerId===form.value.customerId)?.customerName||form.value.person})
