 const missing=[!form.value.modelProductId?'所属产品':'',!form.value.phoneModelId?'实际手机型号':'',!String(form.value.provenance||'').trim()?'实际样品来源说明':'',form.value.moldSetId&&!String(form.value.trialBatch||'').trim()?'实际试模批次／轮次':''].filter(Boolean)
 if(missing.length){formError.value='请补齐：'+missing.join('、');return}
 }if(mode.value==='sample'&&!form.value.resolveSource&&form.value.sampleIdentityId&&identityNeedsReview.value&&!String(form.value.identityReason||'').trim()){formError.value='请填写明确选择已有同物样品码的核对原因';return}if(mode.value==='sample'&&form.value.resolveSource&&form.value.mergeTargetIdentityId&&(!form.value.confirmSameType||!String(form.value.identityReason||'').trim())){formError.value='并入已有同物主码前，请勾选同物确认并填写并码原因';return}if(mode.value==='sample'&&form.value.sourceType==='catalog'){formError.value='请从选品目录登记本次实际收样。';return}busy.value=true;formError.value=''
 try{let saved:PartnerRow;const payload=clone(form.value);payload.refs=clone(refs.value)
 if(kind.value==='samples'){delete payload.currency;delete payload.mode;if(payload.sampleDomain==='model'){payload.sourceType='model';delete payload.sampleKind}if(payload.sourceType==='catalog')payload.person=payload.ownerName}
 if(mode.value==='action'){if(payload.unitPrice==='')delete payload.unitPrice;saved=await partnerAction(kind.value,id.value,action.value,payload)}
 else if(mode.value==='product'){payload.specs=payload.specs.filter((s:BusinessData)=>s.id||s.phoneModelIds?.length||s.specification||s.sources.some((x:BusinessData)=>x.supplierCode));payload.specs.forEach((s:BusinessData)=>{s.name ||= '待确认';s.sources=s.sources.filter((x:BusinessData)=>x.supplierCode);if(!options.value.canWriteMoney)s.sources.forEach((src:BusinessData)=>{for(const key of ['unitPrice','priceCents','currency','terms'])delete src[key]})});saved=await partnerSave(kind.value,payload,payload.id)
 form.value.id=saved.id;form.value.version=saved.version;if(pendingPhoto.value){const result=await uploadPartnerFile(kind.value,saved.id,pendingPhoto.value,{purpose:'photo',version:'V1'});const fresh=await partnerDetail(kind.value,saved.id);saved=await partnerSave(kind.value,{...fresh,refs:[...(fresh.refs||[]),{id:result.attachmentId,type:'file',name:result.fileName,version:result.versionNo}],requestId:newRequestId()},saved.id)}}
 else if(mode.value==='sale'){payload.lines=payload.lines.filter((l:BusinessData)=>l.specId);saved=await partnerSave(kind.value,payload,payload.id)}
 else saved=payload.resolveSource?await partnerAction('samples',id.value,'source_resolve',payload):await partnerSave('samples',payload)
