async function saveRefs(){if(!detail.value)return;busy.value=true;try{await partnerSave(kind.value,{...detail.value,refs:refs.value,requestId:newRequestId()},id.value);await load();dirty.value=false;ElMessage.success(uiText('采用版本已保存'))}finally{busy.value=false}}
