      <template v-if="confirmed"><section class="partner-panel"><h3>{{ uiText("本次办理") }}</h3><div class="partner-inline"><el-button v-if="canMoney&&detail.status!=='closed'" type="primary" @click="startAction('receipt')">{{ uiText("登记收款") }}</el-button><el-button v-if="canWrite&&detail.status!=='closed'" @click="router.push({path:'/partner-fulfilments',query:{from:route.fullPath}})">{{ uiText("引用原需求并检验交付") }}</el-button><el-button v-if="canWrite" @click="router.push({path:'/samples',query:{customerId:detail.customerId,customerContext:detail.customerId,from:route.fullPath}})">{{ uiText("客户样品与寄样") }}</el-button><el-dropdown v-if="canWrite||canMoney" @command="startAction"><el-button>{{ uiText("退货、退款与调整 ▾") }}</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-for="a in moreActions.filter(a=>['refund','amend','close','reopen'].includes(a)?canMoney:canWrite)" :key="a" :command="a">{{uiText(label(a))}}</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></section>
       <section class="partner-panel" v-if="options.canReadMoney"><h3>{{ uiText("供方结算与佣金") }}</h3><div v-for="st in settlements" :key="st.supplierCode" class="partner-item"><div><el-button link @click="master('supplier',st.supplierCode)">{{st.agreement.supplierName||options.suppliers.find(s=>s.code===st.supplierCode)?.name||st.supplierCode}}</el-button><el-tag v-if="st.agreement.review" type="warning" size="small">{{ uiText("待核对") }}</el-tag><template v-if="st.agreement.mode"><p>{{st.agreement.mode==='net'?uiText('扣佣后付供方'):uiText('先付货款再收佣金')}}{{ uiText(" · 约定 V") }}{{st.agreement.version}}</p><p class="muted">{{ uiText("货款待结 ") }}{{formatMoney(st.payRemainingCents)}}{{ uiText(" · 佣金待核销 ") }}{{formatMoney(st.feeRemainingCents)}}</p></template><p v-else class="muted">{{ uiText("约定待补，货款与佣金分别确认") }}</p></div><div class="partner-inline" v-if="canMoney&&detail.status!=='closed'"><el-button @click="startAction('agreement',st.supplierCode)">{{st.agreement.mode?uiText('核对约定'):uiText('确认约定')}}</el-button><template v-if="st.agreement.mode"><el-button :disabled="st.agreement.review" @click="startAction('supplierpay',st.supplierCode)">{{ uiText("付供方") }}</el-button><el-button v-if="st.agreement.mode==='gross'" :disabled="st.agreement.review" @click="startAction('feereceipt',st.supplierCode)">{{ uiText("收佣金") }}</el-button><el-dropdown @command="(a:string)=>startAction(a,st.supplierCode)"><el-button>{{ uiText("退回／冲回 ▾") }}</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="supplierrefund">{{ uiText("收到供方退款") }}</el-dropdown-item><el-dropdown-item command="feerefund">{{ uiText("退回佣金") }}</el-dropdown-item><el-dropdown-item command="offsetreverse">{{ uiText("抵扣冲回") }}</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template></div></div></section>
