    <template v-if="tab==='history'||kind==='samples'"><section class="partner-panel"><h3>{{kind==='samples'?uiText('实物流转记录'):uiText('往来记录')}}</h3><div v-for="event in events" :key="event.id" class="partner-item"><div><strong>{{uiText(label(event.action))}}</strong><p class="muted">{{String(event.time).replace('T',' ').slice(0,19)}} · {{event.operator}} <template v-if="event.data.qty">· {{event.data.qty}}{{ uiText(" 件") }}</template></p><p>{{event.data.reason||event.data.person}}</p></div><el-button link type="primary" @click="inspectRecord(label(event.action)+' · 当时依据',event.data)">{{ uiText("详情") }}</el-button></div><details v-if="detail.revisions?.length"><summary>{{ uiText("历史确认／资料版本") }}</summary><div v-for="rev in detail.revisions" :key="rev.id" class="partner-item"><span>V{{rev.revision}} · {{String(rev.time).slice(0,19)}}</span><el-button link @click="inspectRecord('历史 V'+rev.revision,rev.data)">{{ uiText("查看当时内容") }}</el-button></div></details></section></template>
